create or replace function public._finalize_exam(_session_id uuid, _auto boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  _s public.exam_sessions;
  _existing jsonb;
  _total int;
  _correct int;
begin
  select * into _s from public.exam_sessions where id = _session_id for update;
  if _s.status <> 'in_progress' then
    select jsonb_build_object('score', score, 'correct_count', correct_count, 'total_questions', total_questions, 'max_score', total_questions * 2, 'auto_submitted', auto_submitted)
      into _existing from public.scores where session_id = _session_id;
    return coalesce(_existing, jsonb_build_object('score', 0, 'correct_count', 0, 'total_questions', 0, 'max_score', 0, 'auto_submitted', _auto));
  end if;

  select count(*) into _total from public.questions where course_id = _s.course_id;
  select count(*) into _correct from public.questions q
    where q.course_id = _s.course_id and (_s.answers ->> q.id::text) = q.correct_option;

    values (_s.id, _s.student_id, _s.course_id, _correct * 2, _correct, _total, _auto);

  update public.exam_sessions
    set status = case when _auto then 'timed_out' else 'submitted' end, submitted_at = now()
    where id = _s.id;

  return jsonb_build_object('score', _correct * 2, 'correct_count', _correct, 'total_questions', _total, 'max_score', _total * 2, 'auto_submitted', _auto);
end;
$$;
revoke execute on function public._finalize_exam(uuid, boolean) from public, anon, authenticated;

update public.courses set description='An introduction to management theories, managerial functions and the coordination of people and resources to achieve organisational goals.',reading_plan='{"overview":"Learn management by linking foundational theories to the planning, organising, leading and controlling activities of real organisations. Use examples from Nigerian universities, businesses and public agencies, and practise distinguishing related concepts through short cases.","modules":[{"title":"Week 1-2: Nature and scope of management","topics":["Meaning of management","Efficiency and effectiveness","Levels of management","Managerial roles and skills"],"tasks":["Identify top, middle and first-line managers in an organisation you know.","Compare efficient resource use with effective goal achievement using a workplace example."]},{"title":"Week 3-4: Evolution of management thought","topics":["Scientific management","Fayol’s administrative principles","Weber’s bureaucracy","Human relations approach","Systems and contingency perspectives"],"tasks":["Create a comparison table of Taylor, Fayol, Weber and Mayo.","Explain one strength and one limitation of a rule-based organisation."]},{"title":"Week 5-6: Planning and decision-making","topics":["Organisational objectives","Strategic, tactical and operational plans","SWOT analysis","Decision-making process","Risk and uncertainty"],"tasks":["Prepare a SWOT analysis for a small Nigerian enterprise.","Develop a measurable objective and outline alternative ways to achieve it.","Apply decision-making steps to a staffing problem."]},{"title":"Week 7-8: Organising and staffing","topics":["Division of work and departmentalisation","Authority, responsibility and accountability","Delegation and span of control","Centralisation and decentralisation","Recruitment, selection and induction"],"tasks":["Draw an organisation chart for a small company.","Distinguish delegation from decentralisation in a short case.","Outline a fair process for recruiting and selecting an administrative assistant."]},{"title":"Week 9-10: Leading and motivating people","topics":["Leadership styles","Motivation and Maslow’s needs","Herzberg’s two-factor theory","Workplace communication","Coordination and teamwork"],"tasks":["Compare autocratic, democratic and laissez-faire leadership using workplace examples.","Classify job factors under Herzberg’s theory and explain your choices.","Suggest ways to reduce communication barriers in a team."]},{"title":"Week 11-12: Control and organisational environment","topics":["Control process and performance standards","Feedforward, concurrent and feedback control","Internal and external environment","Business ethics and social responsibility","Management revision cases"],"tasks":["Apply the control cycle to employee attendance or production quality.","Explain how inflation and labour legislation can affect a Nigerian employer.","Analyse a short case involving an ethical management decision."]}],"key_terms":[{"term":"Management","definition":"The process of planning, organising, leading and controlling resources to achieve organisational objectives."},{"term":"Efficiency","definition":"Using resources economically and minimising waste in producing results."},{"term":"Effectiveness","definition":"The extent to which intended objectives are achieved."},{"term":"Planning","definition":"Setting objectives and deciding in advance how to achieve them."},{"term":"Organising","definition":"Arranging tasks, roles and resources to implement plans."},{"term":"Delegation","definition":"Assigning a task and sufficient authority to a subordinate while retaining overall accountability."},{"term":"Span of control","definition":"The number of subordinates who report directly to a manager."},{"term":"Motivation","definition":"The forces that energise, direct and sustain behaviour towards goals."},{"term":"Control","definition":"Setting standards, measuring performance, comparing results and taking corrective action."},{"term":"Corporate social responsibility","definition":"An organisation’s responsibility to consider its effects on society and the environment alongside economic obligations."}],"exam_tips":["Distinguish efficiency from effectiveness and illustrate each with a concrete example.","Associate each management thinker with the correct school and core contribution.","For case questions, identify the relevant management function before recommending action.","Explain differences such as authority versus responsibility and recruitment versus selection precisely.","Use labelled diagrams for organisational structures and apply theories critically rather than treating them as universal rules."]}'::jsonb where slug='ams-101';
) v(p,q,a,b,c,k) where c.slug='ams-101';
update public.courses set description='An introduction to computer systems, software, data processing and safe use of digital tools for academic and workplace tasks.',reading_plan='{"overview":"Study the main components of a computer alongside hands-on practice in managing files and using common productivity applications. Connect technical concepts to tasks such as preparing staff records, writing reports and communicating securely online.","modules":[{"title":"Week 1-2: Computer fundamentals and data","topics":["Characteristics and uses of computers","Data and information","Input-process-output-storage cycle","Computer generations","Binary numbers and data units"],"tasks":["Describe the processing cycle for calculating employee wages.","Convert small whole numbers between binary and decimal.","Prepare a timeline linking early computer generations to their main hardware technologies."]},{"title":"Week 3-4: Hardware and storage","topics":["CPU, control unit and arithmetic logic unit","RAM and ROM","Input and output devices","Secondary storage","Computer categories"],"tasks":["Label the main components in a computer system diagram.","Compare RAM, ROM and an SSD by purpose and data retention.","Choose suitable input and output devices for an HR office."]},{"title":"Week 5-6: Software and operating systems","topics":["System and application software","Operating system functions","Files, folders and extensions","Software licensing","Basic troubleshooting"],"tasks":["Create a clearly labelled folder structure for course materials.","Compare operating systems with word processors and utilities.","Write a safe troubleshooting checklist for a printer that does not respond."]},{"title":"Week 7-8: Productivity applications","topics":["Word processing and document formatting","Spreadsheet cells, formulas and functions","Relative and absolute references","Presentation design","Databases, tables and keys"],"tasks":["Format a one-page business letter using a word processor.","Create a sample payroll worksheet using SUM and AVERAGE without real personal data.","Design an employee table with a suitable primary key."]},{"title":"Week 9-10: Networks and internet services","topics":["LAN and WAN","Internet and World Wide Web","Browsers, search engines and URLs","Email and online collaboration","Cloud computing"],"tasks":["Compare a campus LAN with the wider internet.","Use search terms to locate and evaluate an academic information source.","Draft a professional email with an informative subject and suitable attachment name."]},{"title":"Week 11-12: Digital safety, ethics and applications","topics":["Malware and phishing","Passwords and multifactor authentication","Backups and recovery","Privacy and responsible handling of personal data","Ergonomics and responsible technology use"],"tasks":["Identify warning signs in a simulated phishing email without opening its links.","Plan separate backups and a recovery check for sample staff records.","Review a workstation for safe posture and appropriate screen position."]}],"key_terms":[{"term":"Data","definition":"Raw facts or observations that can be processed to produce useful information."},{"term":"Hardware","definition":"The physical components of a computer system."},{"term":"Software","definition":"Programs and related instructions that direct computer operations."},{"term":"CPU","definition":"The central processing unit that executes instructions and coordinates processing activities."},{"term":"RAM","definition":"Volatile working memory used to hold programs and data currently in use."},{"term":"Operating system","definition":"System software that manages hardware resources and provides services for applications."},{"term":"Spreadsheet","definition":"An application that organises data in cells and supports calculations and analysis."},{"term":"Database","definition":"An organised collection of related data that can be stored, searched and updated."},{"term":"Network","definition":"Connected computing devices that exchange data and share resources."},{"term":"Phishing","definition":"A deceptive attempt to obtain sensitive information or provoke unsafe actions by impersonating a trusted source."}],"exam_tips":["Distinguish data from information, hardware from software and RAM from secondary storage.","Show place values when converting binary numbers and remember that one byte contains eight bits.","Practise spreadsheet formulas directly and check cell ranges and reference types carefully.","Answer security scenarios with specific protective actions rather than claiming any single tool gives complete protection.","Revise practical tasks such as saving files, formatting documents and choosing appropriate application software."]}'::jsonb where slug='ams-103';
) v(p,q,a,b,c,k) where c.slug='ams-103';
update public.courses set description='An introduction to the principles, functions and ethical responsibilities of managing people in organisations.',reading_plan='{"overview":"This course introduces how organisations attract, develop, reward and retain employees while maintaining fair employment relationships. Study each function in sequence, connect it to a Nigerian workplace example, and practise distinguishing related concepts.","modules":[{"title":"Week 1-2: Foundations of Human Resource Management","topics":["Meaning and objectives of HRM","Personnel management and HRM","HR department and line-manager responsibilities","Internal and external influences on HRM"],"tasks":["Read an introductory HRM chapter and summarise four objectives.","Map the HR duties of a supervisor and an HR officer in a Nigerian organisation."]},{"title":"Week 3-4: Job Analysis and Human Resource Planning","topics":["Job analysis methods","Job descriptions and person specifications","Forecasting labour demand and supply","Responses to staff shortages and surpluses"],"tasks":["Draft a job description and person specification for an administrative assistant.","Prepare a simple staffing forecast for a growing retail outlet."]},{"title":"Week 5-6: Recruitment, Selection and Induction","topics":["Internal and external recruitment","Application screening and selection tests","Structured interviews and reference checks","Induction and socialisation"],"tasks":["Compare two recruitment sources using cost and applicant reach.","Develop five job-related interview questions and an induction checklist."]},{"title":"Week 7-8: Learning and Performance","topics":["Training needs assessment","On-the-job and off-the-job training","Training evaluation","Performance appraisal and feedback"],"tasks":["Design a short training plan for newly employed clerks.","Write measurable performance objectives and identify two appraisal errors."]},{"title":"Week 9-10: Motivation and Reward","topics":["Intrinsic and extrinsic motivation","Maslow and Herzberg","Financial and non-financial rewards","Job evaluation and pay equity"],"tasks":["Compare Maslow and Herzberg using workplace examples.","Distinguish basic pay, allowances and non-financial recognition."]},{"title":"Week 11-12: Employment Relations, Welfare and Ethics","topics":["Trade unions and collective bargaining","Grievance and disciplinary procedures","Occupational health, safety and welfare","Equal opportunity, confidentiality and Nigerian employment regulation"],"tasks":["Explain the roles of the Labour Act and trade unions at an introductory level.","Analyse a grievance case and recommend a fair process without assuming all workers have identical legal coverage."]}],"key_terms":[{"term":"Human resource management","definition":"The coordinated management of people to achieve organisational goals while supporting employee wellbeing."},{"term":"Job analysis","definition":"The systematic collection of information about job duties, responsibilities and requirements."},{"term":"Job description","definition":"A written statement of a job’s main duties, responsibilities and reporting relationships."},{"term":"Person specification","definition":"A statement of the qualifications, skills and other attributes required for a job."},{"term":"Recruitment","definition":"The process of attracting suitable applicants for available jobs."},{"term":"Selection","definition":"The process of assessing applicants and choosing those suited to a job."},{"term":"Induction","definition":"The planned introduction of a new employee to the job, colleagues and organisation."},{"term":"Performance appraisal","definition":"The systematic assessment of an employee’s work against agreed criteria."},{"term":"Job evaluation","definition":"A systematic assessment of the relative worth of jobs to support a pay structure."},{"term":"Collective bargaining","definition":"Negotiation between an employer or employers and workers’ representatives over employment terms."}],"exam_tips":["Distinguish recruitment from selection and job analysis from job evaluation.","For essay questions, define the concept, explain its steps and give a relevant workplace example.","Apply motivation theories carefully rather than assuming every employee has identical needs.","Separate performance appraisal of a person from evaluation of a job.","When discussing Nigerian employment law, avoid claiming that every provision covers every category of worker."]}'::jsonb where slug='ehr-121';
) v(p,q,a,b,c,k) where c.slug='ehr-121';