  insert into public.scores (session_id, student_id, course_id, score, correct_count, total_questions, auto_submitted)
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which statement best describes management?','Keeping financial records only','Coordinating resources through planning, organising, leading and controlling','Owning every resource personally','B'),
(2,'A firm meets its production target but wastes excessive materials. It is best described as what?','Effective but inefficient','Efficient but ineffective','Neither effective nor inefficient','A'),
(3,'Which management level normally sets organisation-wide long-term direction?','First-line supervision','Front-desk operations','Top management','C'),
(4,'Which skill involves proficiency in specific job methods and procedures?','Conceptual skill','Political influence','Technical skill','C'),
(5,'Which managerial skill is especially important for understanding the organisation as a whole?','Conceptual skill','Typing speed','Machine operation','A'),
(6,'Who is most closely associated with scientific management?','Elton Mayo','Frederick W. Taylor','Abraham Maslow','B'),
(7,'Which practice reflects scientific management?','Studying tasks systematically to improve work methods','Choosing work methods entirely by habit','Removing all performance standards','A'),
(8,'Which thinker is associated with administrative management principles?','Frederick Herzberg','Douglas McGregor','Henri Fayol','C'),
(9,'What does Fayol’s unity of command principle require?','Every employee should manage two departments','An employee should receive orders from one superior','All decisions should be made by customers','B'),
(10,'Which feature characterises Weber’s ideal bureaucracy?','Appointments based solely on friendship','Formal rules and clearly defined offices','Absence of hierarchy','B'),
(11,'The human relations approach emphasises which factor?','Only machine speed','Only physical inventory','Social relationships and employee attitudes','C'),
(12,'What is the central idea of the contingency approach?','Appropriate management practice depends on the situation','One method is best for every organisation','The environment never affects management','A'),
(13,'Which management function establishes objectives and ways to achieve them?','Controlling','Staffing','Planning','C'),
(14,'Which objective is most clearly measurable?','Improve service somehow','Reduce average customer waiting time to ten minutes by June','Become better whenever possible','B'),
(15,'In SWOT analysis, which item is an external threat?','A new competitor entering the market','A skilled internal workforce','A strong internal training programme','A'),
(16,'What normally comes first in a rational decision-making process?','Identifying the problem','Implementing an unexamined option','Evaluating final results','A'),
(17,'Which statement best distinguishes risk from uncertainty?','Under risk, every outcome is guaranteed','Under risk, outcome probabilities can be reasonably estimated','Under uncertainty, complete outcome probabilities are always known','B'),
(18,'Grouping jobs into finance, marketing and personnel units is which form of departmentalisation?','Geographical','Product','Functional','C'),
(19,'What is authority in an organisation?','The obligation to perform an assigned duty','The legitimate right to make decisions and direct work','The number of employees absent','B'),
(20,'What happens when a manager delegates a task?','The manager loses all overall accountability','The organisational hierarchy automatically disappears','The subordinate receives responsibility and suitable authority','C'),
(21,'What does span of control measure?','The number of direct reports to a manager','The total age of an organisation','The distance between office buildings','A'),
(22,'What is decentralisation?','Reserving every decision for the chief executive','Removing all managerial positions','Dispersing decision-making authority to lower organisational levels','C'),
(23,'Which activity is recruitment rather than selection?','Attracting suitable applicants for a vacancy','Interviewing shortlisted candidates to choose one','Ranking candidates after an aptitude test','A'),
(24,'What is the main purpose of employee induction?','Replacing every future training programme','Helping a new employee understand the job and organisation','Determining the organisation’s annual profit','B'),
(25,'Which leadership style normally involves employees in decision-making?','Democratic','Autocratic','Laissez-faire','A'),
(26,'In Maslow’s conventional hierarchy, which needs are most basic?','Esteem needs','Physiological needs','Self-actualisation needs','B'),
(27,'Under Herzberg’s theory, which is a motivator?','Company policy','Working conditions','Recognition for achievement','C'),
(28,'Which sequence correctly describes the control process?','Take corrective action, ignore results and remove standards','Set standards, measure results, compare and take corrective action','Measure results once and avoid comparisons','B'),
(29,'Inspecting raw materials before production is an example of which control?','Feedback control','Post-production control','Feedforward control','C'),
(30,'Which action best illustrates corporate social responsibility?','Reducing harmful waste affecting a host community','Hiding unsafe working conditions','Bribing an inspector to avoid compliance','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which option best describes a computer?','A device that operates without instructions','An electronic device that processes data according to instructions','A machine used only for numerical calculations','B'),
(2,'Which item is an example of raw data?','Individual employee attendance entries','A monthly attendance summary showing trends','A manager’s interpretation of an absence report','A'),
(3,'Which sequence represents a basic data-processing cycle?','Output, printing, typing and deletion','Storage, shutdown, repair and disposal','Input, processing, output and storage','C'),
(4,'Which technology is associated with first-generation electronic computers?','Microprocessors','Integrated circuits','Vacuum tubes','C'),
(5,'Which technology is associated with second-generation computers?','Transistors','Vacuum tubes','Mechanical gears only','A'),
(6,'What is the decimal value of the binary number 1010?','12','10','8','B'),
(7,'How many bits make one byte?','8','2','16','A'),
(8,'Which component performs arithmetic and logical operations?','Monitor','Keyboard','Arithmetic logic unit','C'),
(9,'What is a major function of the CPU control unit?','Producing printed documents','Coordinating the execution of instructions','Storing files permanently on an SSD','B'),
(10,'Which statement about ordinary RAM is correct?','It permanently stores files without power','Its contents are normally lost when power is removed','It is an output device','B'),
(11,'Which memory is non-volatile and commonly stores firmware?','RAM','CPU registers','ROM','C'),
(12,'Which device is used primarily for input?','Scanner','Projector','Speaker','A'),
(13,'Which device is used primarily for output?','Keyboard','Mouse','Monitor','C'),
(14,'Which device provides secondary storage?','Arithmetic logic unit','Solid-state drive','Control unit','B'),
(15,'Which task is particularly suited to a supercomputer?','Large-scale scientific simulations','Typing a single short letter','Displaying a basic calculator app','A'),
(16,'Which is an example of system software?','An operating system','A presentation slide deck','A payroll worksheet','A'),
(17,'Which task is normally performed by an operating system?','Writing every business report automatically','Managing memory and running processes','Guaranteeing that hardware never fails','B'),
(18,'What does a file extension such as .pdf usually indicate?','The owner’s home address','The physical size of the computer','The file’s format or type','C'),
(19,'Which software category is designed for a particular user task?','Firmware only','Application software','Boot code only','B'),
(20,'Which application is most suitable for formatting a formal letter?','Device driver','Disk partitioning utility','Word processor','C'),
(21,'What identifies the cell at column B and row 4 in a spreadsheet?','B4','4B','BB4','A'),
(22,'Which character normally begins a formula in Excel or similar spreadsheets?','@','#','=','C'),
(23,'Which formula adds the values in cells A1 through A5?','=SUM(A1:A5)','=AVERAGE(A1:A5)','=COUNT(A1:A5)','A'),
(24,'Which spreadsheet reference remains fixed when a formula is copied?','A1','$A$1','A2','B'),
(25,'What is the purpose of a primary key in a database table?','To identify each record uniquely','To make every record identical','To store only images','A'),
(26,'What is a local area network?','Every computer connected worldwide','A network covering a limited area such as an office','A single offline spreadsheet','B'),
(27,'Which statement correctly distinguishes the web from the internet?','The internet is only a collection of web pages','The web and the internet are identical in every respect','The web is one service that operates over the internet','C'),
(28,'Which program is a web browser?','Microsoft Excel','Mozilla Firefox','Windows File Explorer','B'),
(29,'An email requests your password through an unexpected link. What is the safest response?','Reply with your password to confirm ownership','Open the link immediately because it looks official','Do not use the link; verify the request through a trusted channel','C'),
(30,'Which practice best protects staff records against data loss?','Maintain separate backups and periodically test restoration','Keep the only copy on one laptop','Rely solely on renaming the original file','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'What is the central focus of human resource management?','Recording only cash receipts','Managing people to meet organisational goals','Designing production equipment','B'),
(2,'Which activity is normally a line manager’s HR responsibility?','Giving employees day-to-day performance feedback','Setting national employment legislation','Registering all trade unions','A'),
(3,'Which is an external influence on HR planning?','The firm’s internal reporting chart','The firm’s leave approval procedure','Changes in the labour market','C'),
(4,'What does job analysis primarily establish?','The company’s annual sales tax','Job duties and requirements','Each employee’s personal spending','B'),
(5,'Which document mainly states the duties of a post?','Person specification','Applicant reference','Job description','C'),
(6,'Which item belongs in a person specification?','Required spreadsheet skills','Daily departmental duties','The job’s reporting line','A'),
(7,'What is the purpose of human resource planning?','Matching future staffing needs with available people','Guaranteeing that no employee ever resigns','Replacing every permanent worker with a contractor','A'),
(8,'Which action can help address a forecast staff shortage?','Freezing all recruitment indefinitely','Offering voluntary retirement to needed staff','Recruiting suitably qualified employees','C'),
(9,'Which is an example of internal recruitment?','Advertising a vacancy in a national newspaper','Promoting an existing employee to a vacant post','Hiring through an external employment agency','B'),
(10,'How does selection differ from recruitment?','Selection chooses among applicants','Selection attracts the initial applicant pool','Selection forecasts national population growth','A'),
(11,'What characterises a structured interview?','Questions are unrelated to the vacancy','Each candidate sets the assessment criteria','Candidates face consistent, job-related questions','C'),
(12,'What is a main purpose of induction?','Determining the national minimum wage','Helping new employees understand their jobs and organisation','Replacing all future employee training','B'),
(13,'What should normally come first in planning employee training?','Buying equipment without assessment','Identifying training needs','Awarding completion certificates','B'),
(14,'Which is on-the-job training?','Attending an external residential seminar','Studying at an off-site training centre','Coaching a worker while performing normal duties','C'),
(15,'Which evidence best indicates that training improved job performance?','Fewer work errors after training under comparable conditions','The training room’s attractive decoration','The number of refreshments served','A'),
(16,'Which is a measurable performance objective?','Have an excellent attitude at all times','Become the best employee somehow','Process 40 accurate invoices per day','C'),
(17,'What is the halo effect in appraisal?','Allowing one favourable trait to influence all ratings','Assessing each performance criterion independently','Using several sources of performance evidence','A'),
(18,'Which is an example of constructive feedback?','Attacking an employee’s personality publicly','Discussing specific errors and agreeing improvement steps','Avoiding any discussion of performance','B'),
(19,'Which reward is primarily intrinsic?','A transport allowance','An annual cash bonus','Satisfaction from mastering a challenging task','C'),
(20,'In Maslow’s hierarchy, which needs concern protection from danger and insecurity?','Esteem needs','Safety needs','Self-actualisation needs','B'),
(21,'According to Herzberg, which is a motivator?','Achievement','Company policy','Working conditions','A'),
(22,'What does job evaluation assess?','An applicant’s interview confidence','The relative worth of jobs','An employee’s daily attendance alone','B'),
(23,'Which payment is an example of a financial reward?','A housing allowance','A letter of appreciation without payment','Greater decision-making autonomy','A'),
(24,'What is the main purpose of collective bargaining?','Selecting the company’s external auditors','Setting retail prices for customers','Negotiating employment terms with workers’ representatives','C'),
(25,'What is an employee grievance?','A planned market expansion','A complaint about an employment-related issue','A statement of company sales revenue','B'),
(26,'Which action supports fair disciplinary practice?','Imposing punishment before checking the facts','Refusing to explain the allegation','Giving the employee an opportunity to respond','C'),
(27,'Which is an occupational safety measure?','Providing suitable protective equipment and training','Ignoring reported hazards to save time','Using damaged electrical cables until they fail','A'),
(28,'Which practice protects employee confidentiality?','Posting medical records on a public noticeboard','Sharing salary records with unrelated visitors','Restricting personnel-record access to authorised users','C'),
(29,'What does equal opportunity in selection require?','Preferring relatives regardless of competence','Assessing candidates using relevant, fair criteria','Rejecting applicants solely because of ethnicity','B'),
(30,'Which Nigerian statute is a major source of basic employment rules for workers within its scope?','Labour Act','Companies Income Tax Act','Customs and Excise Management Act','A')
